import {monthLabel,paymentLabels} from './domain.js';
import {itemStatusLabels,priceKindLabels,isConfirmedPurchase} from './preview-workflow.js';
export const poStatusLabels={pending:'มีรายการรออนุมัติ',budget_approved:'มีวงเงินประมาณการ',approved:'อนุมัติแล้ว',received:'รับสินค้าแล้ว',closed:'ปิดใบ PO แล้ว',rejected:'ไม่อนุมัติทุกรายการ',revision_requested:'มีรายการพักการอนุมัติ',mixed:'อยู่ระหว่างดำเนินการ'};
export async function buildPreviewWorkbook(report,month,ExcelJS=globalThis.ExcelJS){
 if(!ExcelJS)throw Error('ส่วนสร้างไฟล์ Excel โหลดไม่สำเร็จ กรุณารีโหลดหน้าแล้วลองอีกครั้ง');
 const workbook=new ExcelJS.Workbook();workbook.creator='PO The Grands — Preview';workbook.created=new Date();
 const summary=workbook.addWorksheet('สรุปทดลอง',{views:[{state:'frozen',ySplit:4}]});summary.columns=[{width:34},{width:22}];summary.addRow(['PO The Grands · ข้อมูลสาธิต']);summary.addRow(['สรุปเดือน',monthLabel(month)]);summary.addRow(['ยอดซื้อราคายืนยัน · อนุมัติ/รับแล้ว',report.total_cents/100]);summary.addRow(['วงเงินประมาณการ · ยังไม่นับยอดซื้อ',report.budget_authorized_cents/100]);summary.addRow(['รายการรออนุมัติหรือแก้ไข',report.pending_count]);summary.addRow(['รายการไม่อนุมัติ',report.rejected_count]);summary.getRow(1).font={bold:true,size:18,color:{argb:'FF001D51'}};summary.getCell('B3').numFmt=summary.getCell('B4').numFmt='฿#,##0.00';
 const sheet=workbook.addWorksheet('รายการสินค้า',{views:[{state:'frozen',ySplit:1}]});sheet.columns=[{header:'เลข PO',key:'po',width:22},{header:'วันที่ PO',key:'date',width:14},{header:'ผู้ขอ',key:'requester',width:20},{header:'สถานะใบ PO',key:'poStatus',width:20},{header:'แผนก/สาขา',key:'department',width:20},{header:'สินค้า',key:'name',width:28},{header:'สถานะรายการ',key:'state',width:26},{header:'ชนิดราคา',key:'priceKind',width:18},{header:'ครั้งที่แก้ไข',key:'revision',width:14},{header:'ราคาต่อหน่วย',key:'unitPrice',width:16},{header:'ประเภทภาษี',key:'vatType',width:13},{header:'จำนวน',key:'qty',width:12},{header:'หน่วย',key:'unit',width:14},{header:'การชำระเงิน',key:'payment',width:16},{header:'ก่อน VAT',key:'base',width:16},{header:'VAT',key:'tax',width:14},{header:'รวมสุทธิ',key:'gross',width:16},{header:'วงเงินประมาณการ',key:'budget',width:18},{header:'ยอดซื้อที่นับรายงาน',key:'eligible',width:20},{header:'รายละเอียด / สเปค',key:'spec',width:38},{header:'แหล่งซื้อ',key:'source',width:28},{header:'หมายเหตุ',key:'note',width:32}];
 for(const po of report.rows)for(const item of po.items){const countable=isConfirmedPurchase(item),budget=item.state==='budget_approved';sheet.addRow({po:po.po_number,date:po.po_date,requester:po.requester_name,poStatus:poStatusLabels[po.status]||po.status,department:item.department||po.department||'',name:item.name,state:itemStatusLabels[item.state]||item.state,priceKind:priceKindLabels[item.price_kind]||item.price_kind,revision:item.revision,unitPrice:Number(item.unit_price),vatType:item.vat?'VAT 7%':'NON VAT',qty:Number(item.qty),unit:item.unit||'',payment:paymentLabels[item.payment_method]||'ไม่ระบุ',base:item.base_cents/100,tax:item.tax_cents/100,gross:item.total_cents/100,budget:budget?item.total_cents/100:0,eligible:countable?item.total_cents/100:0,spec:item.spec,source:item.source,note:item.note||''});}
 for(const key of ['unitPrice','base','tax','gross','budget','eligible'])sheet.getColumn(key).eachCell((cell,row)=>{if(row>1)cell.numFmt='฿#,##0.00';});sheet.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};sheet.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF001D51'}};sheet.autoFilter={from:{row:1,column:1},to:{row:1,column:sheet.columnCount}};sheet.eachRow(row=>{row.alignment={vertical:'top',wrapText:true};});
 return workbook;
}
export async function downloadPreviewReport(report,month){const workbook=await buildPreviewWorkbook(report,month);const buffer=await workbook.xlsx.writeBuffer(),blob=new Blob([buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`PO-The-Grands-ตัวอย่าง-${month}.xlsx`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
